const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрити меню':'Відкрити меню')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#service').value=button.dataset.service;if(button.dataset.prompt){const message=document.querySelector('[name="message"]');if(!message.value.trim()||message.dataset.generated===message.value){message.value=button.dataset.prompt;message.dataset.generated=message.value}}document.querySelector('#booking').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}));
document.querySelector('#request-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const text=`Вітаю, M Avto Service! Прошу зв’язатися зі мною щодо обслуговування авто.\nІм’я: ${d.get('name')}\nТелефон: ${d.get('phone')}\nАвтомобіль: ${d.get('car')}\nПослуга: ${d.get('service')}\nКоментар: ${d.get('message')||'—'}`;document.querySelector('#prepared').value=text;const isIOS=/iPad|iPhone|iPod/.test(navigator.userAgent);document.querySelector('#sms').href='sms:+380951195333'+(isIOS?'&':'?')+'body='+encodeURIComponent(text);document.querySelector('#result').hidden=false;document.querySelector('#result').scrollIntoView({behavior:'smooth',block:'nearest'})});document.querySelector('#copy').addEventListener('click',async()=>{const el=document.querySelector('#prepared');try{await navigator.clipboard.writeText(el.value);document.querySelector('#copy-status').textContent='Текст скопійовано. Вставте його в повідомлення сервісу.'}catch{el.focus();el.select();document.querySelector('#copy-status').textContent='Виділіть і скопіюйте текст вручну.'}});

const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const motionButton=document.querySelector('#motion-toggle');
function setMotion(paused){document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Увімкнути анімацію':'Зупинити анімацію'}
setMotion(reduced.matches);motionButton.addEventListener('click',()=>setMotion(!document.body.classList.contains('motion-paused')));
const progress=document.querySelector('.reading-progress');let scheduled=false;window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${total>0?scrollY/total:0})`;scheduled=false})}},{passive:true});
document.querySelectorAll('.service-detail').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)document.querySelectorAll('.service-detail').forEach(other=>{if(other!==detail)other.open=false})}));